1	import { timestampDate } from "@bufbuild/protobuf/wkt";
2	import { createContext, useContext } from "react";
3	import { useLocation } from "react-router-dom";
4	import { useView } from "@/contexts/ViewContext";
5	import type { Memo } from "@/types/proto/api/v1/memo_service_pb";
6	import { MemoRelation_Type } from "@/types/proto/api/v1/memo_service_pb";
7	import type { User } from "@/types/proto/api/v1/user_service_pb";
8	import type { PreviewMediaItem } from "@/utils/media-item";
9	import { RELATIVE_TIME_THRESHOLD_MS } from "./constants";
10	
11	export interface MemoViewContextValue {
12	  memo: Memo;
13	  creator: User | undefined;
14	  currentUser: User | undefined;
15	  parentPage: string;
16	  cardWidth: number;
17	  isArchived: boolean;
18	  readonly: boolean;
