22	  toggleBlurVisibility: () => void;
23	  openPreview: (items: string | string[] | PreviewMediaItem[], index?: number) => void;
24	}
25	
26	export const MemoViewContext = createContext<MemoViewContextValue | null>(null);
27	
28	export const useMemoViewContext = (): MemoViewContextValue => {
29	  const context = useContext(MemoViewContext);
30	  if (!context) {
31	    throw new Error("useMemoViewContext must be used within MemoViewContext.Provider");
32	  }
33	  return context;
34	};
